using CarKit.Maui;
using CarKit.Sample.Car;
using Microsoft.Extensions.Logging;
using Microsoft.Maui.LifecycleEvents;

namespace CarKit.Sample;

public static class MauiProgram
{
	public static MauiApp CreateMauiApp()
	{
		var builder = MauiApp.CreateBuilder();
		builder
			.UseMauiApp<App>()
			// Categories come from <CarKitCategories> in the .csproj; only the car handler is set here
			.UseCarKit(car => car.UseHandler<SampleCarAppHandler>())
			.ConfigureLifecycleEvents(events =>
			{
#if IOS
				// With the scene manifest (generated by CarKit), iOS delivers the URL to the scene (SceneOpenUrl), not to the app
				// delegate's OpenUrl
				events.AddiOS(ios => ios
					.SceneOpenUrl((_, contexts) =>
					{
						foreach (var context in contexts)
						{
							SampleDiagnostics.AppLink(new Uri(context.Url.AbsoluteString!));
						}

						return true;
					})
					.OpenUrl((_, url, _) =>
					{
						SampleDiagnostics.AppLink(new Uri(url.AbsoluteString!));
						return true;
					}));
#endif
			})
			.ConfigureFonts(fonts =>
			{
				fonts.AddFont("OpenSans-Regular.ttf", "OpenSansRegular");
				fonts.AddFont("OpenSans-Semibold.ttf", "OpenSansSemibold");
			});

#if DEBUG
		builder.Logging.AddDebug();
#endif
#if ANDROID
		builder.Logging.AddProvider(new LogcatLoggerProvider());
#endif

		return builder.Build();
	}
}
